/bin/bash -lc "cat <<'EOF' > /vercel/sandbox/app/components/UserPreferences.tsx
import { cookies, headers } from \"next/headers\";

function getPreferredLanguage(acceptLanguage: string | null) {
  if ("'!acceptLanguage) return "unknown";

  const firstLanguage = acceptLanguage.split(",")[0]?.trim();
  return firstLanguage || "unknown";
}

export default function UserPreferences() {
  const themeCookie = cookies().get("theme");
  const theme = themeCookie?.value || "light";

  const acceptLanguage = headers().get("accept-language");
  const preferredLanguage = getPreferredLanguage(acceptLanguage);

  return (
    <section>
      <h2>Current Preferences</h2>
      <p>
        Theme: <strong>{theme}</strong>
      </p>
      <p>
        Preferred language: <strong>{preferredLanguage}</strong>
      </p>
    </section>
  );
}
EOF'

